import json, hashlib, datetime
from pathlib import Path
H = Path(__file__).resolve().parents[1]
p = H / 'PREREG_R2.json'
x = dict(round='R2', frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(), parent='PREREG_R1.json; heldout recall failed in both jaws', capability='Transfer I/C/P/M regions with a monotone coordinate along the arch, then reuse unchanged measured-pose contact maps', obstacle='Euclidean nearest centroid confuses thin canine region and crown radial thickness', changed_operation='Replace 2D nearest-prototype distance with label-free angular arch coordinate, remove radial coordinate, fit three ordered boundaries by balanced per-region training misclassification', equation='theta=atan2(abs(xnormalized),0.25+(ynormalized+1)/2); three thresholds partition ordered I,C,P,M', assumptions='Same label-free RAS/quantile frame; monotone anatomical class order, no true tooth segmentation or individual FDI claims', train='Same50 official training arches/jaw; deterministic hist512bins [0,pi], balanced class totals; dynamic program fits thresholds using training only', validation='NEW official heldout hashes31..60 per jaw, no tuning on R1 validation; 30 per jaw', metrics=dict(macro_region_recall_min=0.85, anterior_posterior_error_max=0.05, numerical_conservation_max=1e-07, refinement_L1_pp_max=5), strongest_control='Frozen R1 two-dimensional nearest8type prototypes, same new heldout labels and same B2B maps; contact-area still primary equally informed load control', falsifier='New heldout gate fails, anterior/posterior error >5%, or measured bite region maps unstable on refinement', cost=dict(preparation='Reuse read maps, not copied source trees', fit='training label histogram CPU/wall measured', validation='60 new arches, 200 raw ZIP relabels and12 fine maps', discovery='R1 failed validation retained', questions='no acquisition force or support inferred', fallback='Only anterior/posterior if fine4-class gate fails; classforces explicit UNKNOWN'), external_referent=dict(kind='published_dataset', locator='https://osf.io/xctdy/; raw/segmentation_r2_validation.json with exact paths/hashes', compared_quantity='Heldout four-region vertex labels', refutes_us=True))
if p.exists():
    raise RuntimeError('Frozen')
p.write_text(json.dumps(x, indent=2) + '\n')
p.with_suffix('.json.sha256').write_text(hashlib.sha256(p.read_bytes()).hexdigest() + '  ' + p.name + '\n')
